function rename(team, name) {
  team.name = name;
  name = "ignored";
}

function relocate(team) {
  team = { name: team.name, city: "Rome" };

  return team;
}

const crew = { name: "Red", city: "Oslo" };
const label = "Blue";
rename(crew, label);
const moved = relocate(crew);

console.log(crew.name, label);
console.log(crew.city, moved.city);
console.log(moved.name);
